#define PI 3.1415926535897932384626433832795
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    uv.x *= iResolution.x/iResolution.y;
    uv.x -= .35;
    uv -= .5;

    vec2 still = uv;

    float anim = tan(mod(iTime,PI*2.));

    uv.x *= cos(uv.y);
    uv.y *= tan(uv.y)/sin(uv.x);

    uv /= tan(uv*iTime);

    float red = step(.4+anim,length(uv)/step(.3+anim,length(uv)));
    uv = still;

    uv.x *= cos(uv.x)/tan(uv.y);
    uv.y *= sin(uv.x);

    uv /= cos(uv*iTime);

    float green = step(.7+anim,length(uv)/step(.4+anim,length(uv)));
    uv = still;


    uv.x *= cos(uv.x)*tan(uv.y);
    uv.y *= tan(uv.x)/sin(uv.y);

    uv /= sin(uv*iTime);

    float blue = step(.8+anim,length(uv)/step(.4+anim,length(uv)));
    uv = still;

    vec3 col = vec3(red,green,blue);

     uv.x *= cos(uv.x)/tan(uv.y);
    uv.y *= tan(uv.x)*sin(uv.y);

    uv /= sin(uv*iTime);
    col *= step(.7+anim,length(uv)/step(.4+anim,length(uv)));

    // Output to screen
    fragColor = vec4(col,1.0);
}
